# ENHANCED_PROGRAM_V1: import additional modules for robustness
import json, re, time
from typing import Any, Dict

class RetryException(Exception):
    """Raised to trigger a retry of the LLM call."""
    pass

def safe_parse_json(text: str) -> Dict[str, Any]:
    """Parse JSON tolerant to minor formatting issues."""
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        # Attempt to extract the first {...} block
        match = re.search(r'\{.*\}', text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group(0))
            except json.JSONDecodeError:
                pass
        raise RetryException("Unable to parse JSON from LLM output")

def validate_response(data: Dict[str, Any]) -> None:
    """Validate minimal schema; raise RetryException on failure."""
    required_keys = {"action", "answer"}
    if not required_keys.issubset(data.keys()):
        raise RetryException(f"Missing required keys in response: {required_keys - data.keys()}")
    if not all(isinstance(data[k], str) for k in required_keys):
        raise RetryException("Schema validation failed: values must be strings")

def has_sufficient_evidence(state: Dict[str, Any], goal: str) -> bool:
    """Check if retrieved context already contains the goal."""
    retrieved = state.get("retrieved", "")
    return goal.lower() in retrieved.lower()

def should_use_tool(state: Dict[str, Any], query: str) -> bool:
    """Heuristic to decide if retrieval is needed."""
    keywords = ["latest", "statistics", "reference", "data", "report"]
    return any(kw in query.lower() for kw in keywords) and not state.get("retrieved")

MAX_RETRIES = 3  # ENHANCED_PROGRAM_V1: adaptive retry limit

def with_retry(func, *args, **kwargs):
    """Execute func with retry on RetryException or premature give‑up."""
    attempts = 0
    while attempts < MAX_RETRIES:
        try:
            return func(*args, **kwargs)
        except RetryException as e:
            attempts += 1
            if attempts >= MAX_RETRIES:
                raise
            # Slight back‑off and modify prompt hint for next try
            time.sleep(0.2 * attempts)
            kwargs.setdefault("retry_hint", f"Please try again. Attempt {attempts+1}.")
    raise RetryException("Maximum retries exceeded")
''')
